const templateExperienceData=[{"slug": "icma-papers", "time": "2025.10 — 2026.05", "title": "IEEE ICMA · 2 PAPERS ACCEPTED", "shortTitle": "IEEE ICMA 论文（四作）", "summary": "在多智能体强化学习研究中，负责实验方案设计、评测体系搭建与仿真验证。通过定义可比较、可复现的实验标准，将算法假设转化为可被同行评审的量化证据，两篇论文被 IEEE ICMA 录用。", "tags": ["实验设计", "评测体系", "MADDPG", "Multi-Agent RL", "可复现性"], "facts": ["2 篇 IEEE ICMA 录用", "独立负责 RL 实验方案", "独立负责仿真验证体系"], "story": {"起点": "研究聚焦大规模集群对抗中的多智能体决策——当智能体数量从个位数扩展到数十甚至上百时，单体策略、团队协同和训练稳定性之间的相互作用变得极其复杂。我的角色不是提出算法公式，而是设计一套实验体系来回答一个关键产品问题：这个改进到底是不是真的有效，还是只是参数调得好？", "挑战": "多智能体强化学习的训练结果对环境、随机种子、奖励函数和超参数高度敏感。规模扩大后，收敛速度、策略稳定性和评测口径都会成为混淆因素。如果实验链路不一致——比如两次实验用了不同的随机种子但没有控制变量——就很难判断性能提升来自算法本身还是偶然波动。这跟产品 A/B 测试中排除混淆变量的逻辑完全一样。", "行动": "围绕 DDPG、MADDPG 及改进策略，我设计了标准化的实验方案：固定环境配置、统一评测口径、记录完整的训练曲线和行为日志。每次算法改动后，我不仅看最终胜率，还持续追踪奖励变化趋势、策略行为分布和不同方案之间的统计显著性，确保结论经得起复核。最后将训练结果转化为论文中可以解释和验证的证据链。", "结果": "相关实验支撑两篇论文被 2026 IEEE ICMA 录用。更重要的是，这套\"定义假设 → 控制变量 → 量化验证 → 形成证据\"的工作方式，后来成了我判断任何一件事的默认路径：先问它到底成不成立，再谈它有多好。", "产品思考": "评测设计决定了团队怎么发现问题、怎么选版本、怎么分配精力。指标不只是用来证明效果，它同样决定了你会先看到哪个问题。一个不能稳定复现的提升，再漂亮也不可信。"}}, {"slug": "paddle-internship", "time": "2025.12 — 2026.07", "title": "Paddle API兼容性适配，增强框架易用性，降低开发成本", "shortTitle": "百度飞桨 · 远程实习", "summary": "从识别迁移痛点出发，定义 API 兼容规范与质量门禁，设计 AI-native 测试工作流并推动落地。", "tags": ["Developer Experience", "API 设计规范", "质量体系搭建", "Paddle", "PyTorch", "AI-native Workflow"], "facts": ["100+ PRs 交付", "定义五维度 API 兼容规范", "设计 AI-native 测试工作流", "覆盖 4+ 国际标准材料数据集"], "story": {"起点": "实习面对的是一个百万级开发者生态中的核心增长问题：如何让 PyTorch 用户零摩擦迁移到飞桨。这表面上是一个\"补齐 API\"的工程任务，实质上是一个开发者体验产品——我需要回答：开发者在什么场景下会撞到不兼容？哪些不兼容是阻断性的必须优先解决？如何让兼容质量不依赖个人经验，而是成为团队可重复运转的体系？", "挑战": "兼容工作跨越 Python 与 C++ 两层语义，任何参数默认值、返回行为、异常抛出的细微差异，都可能在用户迁移模型时变成难以定位的故障。存量接口缺乏系统化的双端行为验证，人工逐项补测效率低且不可持续。同时，材料科学数据管线需要接入 CIF、XYZ、LMDB、压缩 JSON 等多种异构格式，数据规模扩大后 I/O 成为瓶颈——需要在数据质量和接入效率之间做权衡。", "行动": "我从开发者使用场景出发，将 API 兼容需求规范化为五个维度：参数签名、默认值、返回值语义、原地操作行为、异常行为——这本质上是一份产品规范文档，让团队对\"什么叫兼容\"有统一标准。在实现决策上，我建立了\"装饰器适配 → C++ 下沉 → 修改原 API → 新增 API\"的决策树，确保每种方案选择都有明确的产品理由而非技术惯性。比如对高频使用的 std / var 等统计接口，我选择将行为拆为显式算子链来保证语义完全对齐，即使实现成本更高——因为用户对这类接口的行为一致性期待最高。", "产品方法": "质量体系的搭建是这个项目中最\"产品\"的部分。我把兼容测试的隐性经验蒸馏为结构化的 skill 文档，用 AI 工具批量生成测试用例并在独立会话中交叉验证，形成了一套 AI-native 的测试工作流。这不是\"用 AI 写代码\"——本质上是把一个人的领域知识转化为团队可重复执行的质量流程，让正确的事情不依赖特定的人就能持续发生。同时，这套工作流产出的差异报告会标注文件定位、用例、diff 和诊断建议，降低了团队其他成员参与兼容工作的门槛。", "结果": "累计主导百余个 PR 合入飞桨主仓，万行级代码贡献。兼容层获得系统化的 PyTorch-Paddle 双端行为测试覆盖，并能自动产出结构化差异报告。材料数据管线覆盖 Jarvis-DFT2D、tmQM、OC20、OMol25 等国际标准数据集。", "产品思考": "框架兼容本质上是一个开发者体验产品。用户不关心内部用了多少算子，只关心迁移是否稳定、报错是否可理解、行为是否可预期。这段经历让我理解：最有价值的不是自己写出最好的代码，而是定义\"好\"的标准、设计让标准持续运转的系统，并用数据驱动迭代。需求优先级、规范定义、质量体系、用工具放大团队——这些比代码更耐用。"}}, {"slug": "competitions", "time": "2023.12 — 2025.09", "title": "智能车、电子设计与交通预测等科创竞赛 —— 嵌入式 + AI模型综合应用", "shortTitle": "科创竞赛（均一作）", "summary": "在真实硬件、边缘算力和竞赛指标的约束下，独立完成机器人控制与交通时序预测系统的需求分析、架构决策与交付验证。在精度、延迟、稳定性与算力之间做系统性权衡，以多项国家级奖项验证方案可行性。", "tags": ["需求定义", "架构决策", "ROS2", "Autonomous Driving", "约束权衡", "6 项国奖/省奖"], "facts": ["国家级二等奖", "国家级三等奖", "东北赛区一等奖", "多项省级奖项"], "story": {"起点": "竞赛把课堂中的控制、视觉和深度学习问题放进了真实约束：传感器会抖动，通信会延迟，边缘设备算力只有嵌入式的水平，但比赛成绩只看最终效果。资源永远不够，但交付标准不会降。", "挑战": "双车跟随任务要在同一时间窗口内处理车道线检测、前车位姿估计、跟随控制三个子问题，还需要从仿真迁移到实车，仿真中跑得好的策略上了实车可能完全失效。交通时序预测则需要在历史流量、时间周期和空间关联中提取有效信号，同时避免模型过拟合训练数据——这直接决定了预测在真实场景中是否可用。", "行动": "机器人系统侧，我定义了感知、决策、控制解耦的多节点架构——这本质上是一次系统级的产品决策：解耦意味着更高的通信开销，但换来的是每个模块可以独立调试、独立优化，在竞赛场景下大幅降低了联调成本。控制策略上，在 PID 和 Pure Pursuit 之间做了场景驱动的取舍：直道用 PID 保证响应速度、弯道用 Pure Pursuit 保证轨迹精度。算法侧，我构建了 LSTM 与 Transformer 两种方案做对比，结合滑动窗口、周期特征工程和学习率衰减策略优化泛化能力——每次方案选型都基于验证集的量化对比，而非个人偏好。", "结果": "相关方案获得智能汽车竞赛国家级二等奖、交通科技竞赛国家级三等奖、东北赛区一等奖，以及电子设计竞赛和华为 ICT 大赛等省级奖项——总计 6 项。更重要的是，这些奖项验证的不是\"代码写得多好\"，而是\"在给定约束下方案决策是否正确\"。", "产品思考": "竞赛让我理解了\"能运行\"和\"可交付\"之间的巨大鸿沟。真实系统需要在精度、延迟、稳定性、算力和调试成本之间做持续权衡。这些约束不该只被当成研发的难题——它们决定了在给定条件下，什么方案才算真的能交付。"}}, {"slug": "heu-education", "time": "2023.09 — PRESENT", "title": "哈尔滨工程大学 · 电气自动化(大四) → 保研控制", "shortTitle": "教育经历", "summary": "以电气自动化为基础，把控制、软件、深度学习与机器人拼成一条能互相咬合的能力线。已保研至本校智能科学与技术。", "tags": ["Electrical Engineering", "控制科学", "Deep Learning", "Robotics", "跨学科"], "facts": ["电气工程及其自动化", "已保研至本校智能科学与技术", "ROS2 / Linux / CUDA", "控制 / 机器人方向"], "story": {"起点": "从电气工程出发，我很快发现机器人这类系统是控制、感知、决策与交互的交叉——单一专业给不出完整视角。于是我不把视野局限在课程里，而是用项目驱动，一块块补齐。", "挑战": "真正难的不是精通每一层，而是对每一层都有足够理解，能在工程、算法和场景之间做翻译和取舍。这意味着必须同时接触硬件层（嵌入式、传感器）、系统层（ROS2、Linux、CUDA）、算法层（深度学习框架、RL、VLA）和任务层（需求定义、场景分析、评测设计）。", "行动": "我系统学习了 Python、C++ 和数据结构与算法，深入阅读 PyTorch 和 Paddle 的 API 架构与算子实现，在 Linux、CUDA、Docker 和 CMake 环境中完成工程实践。然后通过智能车竞赛（硬件+控制）、交通预测（算法+数据）、百度实习（框架+质量体系）和人形机器人项目（场景+部署）把各层知识串成可用的能力链。已保研至本校智能科学与技术，是想在\"决策—执行\"这条核心链路上再往下扎一层。", "结果": "形成了从底层工程到模型训练、从机器人控制到任务定义的复合能力。这段路径的每一步，其实都在回答同一个问题：我能不能把东西真正做出来。", "产品思考": "教育阶段最重要的收获不是一份技术清单，而是建立了进入陌生复杂系统的方法论：先理解目标和约束边界，再找到关键链路，用可验证的项目结果持续校正自己的判断。这套方法在陌生领域里同样适用。"}}];
